// Fix: Force correct mimeType based on file extension
const binaryKeys = Object.keys($binary);
if (binaryKeys.length === 0) {
  throw new Error('No binary data received');
}
const key = binaryKeys[0];
const binaryInfo = $binary[key];
const ext = (binaryInfo.fileName || '').split('.').pop().toLowerCase();

const mimeTypes = {
  pdf: 'application/pdf',
  txt: 'text/plain',
  md: 'text/markdown',
  doc: 'application/msword',
  docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  png: 'image/png',
  jpg: 'image/jpeg',
  jpeg: 'image/jpeg'
};

const correctMimeType = mimeTypes[ext] || 'application/octet-stream';

// Get headers for metadata
const headers = $json.headers || {};
const tenantId = headers['x-tenant-id'] || '00000000-0000-0000-0000-000000000001';
const documentId = headers['x-document-id'] || '';
const knowledgeBaseId = headers['x-knowledge-base-id'] || '';

// Create new item with corrected binary data
const items = [{
  json: {
    tenantId,
    documentId,
    knowledgeBaseId,
    binaryKey: key
  },
  binary: {
    [key]: {
      ...binaryInfo,
      mimeType: correctMimeType
    }
  }
}];

return items;

const webhookData = $('1. Webhook').item.json;
const headers = webhookData.headers || {};
const metadata = $('2. Fix MIME Type').item.json;
const driveResult = $('3. Google Drive').item.json;

return [{
  json: {
    success: true,
    documentId: metadata.documentId,
    tenantId: metadata.tenantId,
    filename: driveResult.name || '',
    fileUrl: 'https://drive.google.com/file/d/' + (driveResult.id || '') + '/view',
    storageProvider: 'gdrive',
    gdriveFileId: driveResult.id || '',
    timestamp: new Date().toISOString(),
    message: 'Archivo subido a Google Drive con mimeType corregido'
  }
}];
